func (q *Queries) RewrapTOTP(ctx context.Context, arg RewrapTOTPParams) (int64, error) {
	result, err := q.db.Exec(ctx, rewrapTOTP,
		arg.WrappedDek,
		arg.KeyVersion,
		arg.UserID,
		arg.OldWrappedDek,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const sealedSmtpPassword = `-- name: SealedSmtpPassword :many
SELECT password_ciphertext, password_wrapped_dek, password_key_version FROM smtp_settings WHERE password_ciphertext IS NOT NULL
`

type SealedSmtpPasswordRow struct {
	PasswordCiphertext []byte
	PasswordWrappedDek []byte
	PasswordKeyVersion pgtype.Int2
}

func (q *Queries) SealedSmtpPassword(ctx context.Context) ([]SealedSmtpPasswordRow, error) {
	rows, err := q.db.Query(ctx, sealedSmtpPassword)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SealedSmtpPasswordRow
	for rows.Next() {
		var i SealedSmtpPasswordRow
		if err := rows.Scan(&i.PasswordCiphertext, &i.PasswordWrappedDek, &i.PasswordKeyVersion); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const secretKeyVersions = `-- name: SecretKeyVersions :many
SELECT DISTINCT v::smallint AS version FROM (
  SELECT secret_key_version AS v FROM credentials WHERE secret_key_version IS NOT NULL
  UNION SELECT secret_key_version FROM cloud_accounts WHERE secret_key_version IS NOT NULL
  UNION SELECT key_version FROM mfa_totp WHERE secret_ciphertext <> '\x00'::bytea
  UNION SELECT password_key_version FROM smtp_settings WHERE password_key_version IS NOT NULL
) x ORDER BY 1
`

// Master key versions in use, across every table holding a sealed secret (startup check, rotation).
func (q *Queries) SecretKeyVersions(ctx context.Context) ([]int16, error) {
	rows, err := q.db.Query(ctx, secretKeyVersions)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []int16
	for rows.Next() {
		var version int16
		if err := rows.Scan(&version); err != nil {
			return nil, err
		}
		items = append(items, version)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

